{
  "answerable": true,
  "sentences": [
    {
      "text": "Climate regulation could raise the company's costs and require substantial capital and operating expenditures, harming its financial results.",
      "support": [
        {
          "source": "S3",
          "quote": "could significantly increase our costs, reduce demand for fossil energy derived products, impact the cost and availability of capital"
        },
        {
          "source": "S4",
          "quote": "We expect to continue to incur substantial capital expenditures and operating costs as a result of our compliance with existing and future environmental laws and regulations."
        }
      ]
    },
    {
      "text": "It may also restrict access to favorable capital and increase financing costs, further damaging results of operations.",
      "support": [
        {
          "source": "S2",
          "quote": "our access to capital on terms we find favorable (if it is available at all) may be limited and our costs may increase or our business and results of operations may be otherwise adversely affected."
        }
      ]
    },
    {
      "text": "Failure to comply could trigger penalties, litigation and asset impairments, negatively affecting cash flow and earnings.",
      "support": [
        {
          "source": "S4",
          "quote": "could result in administrative or civil penalties, criminal fines, other enforcement actions or third‑party litigation against us."
        },
        {
          "source": "S6",
          "quote": "potentially resulting in the reduction to the economic end‑of‑field life of certain assets and an impairment of the associated net book value."
        }
      ]
    }
  ]
}
